import {header,icon} from '../ui.js';
import {words} from '../content.js';
export function render(state) {
  return `${header('学习偏好','你的节奏，应该由你决定','library')}<form id="learning-settings-form"><section class="settings-block"><div class="settings-block-title"><span>${icon('book',21)}</span><h2>每日学习量</h2></div><p class="muted">优先复习，再用剩余名额学新词。</p><label class="field-label" for="daily-limit">每天复习与新学总上限</label><select id="daily-limit" name="dailyLimit">${[10,20,30,50,80].map(n=>`<option value="${n}" ${state.learning.dailyLimit===n?'selected':''}>${n} 词 / 天</option>`).join('')}</select><label class="field-label" for="new-limit">其中新词最多</label><select id="new-limit" name="newLimit">${[0,5,10,20,30].map(n=>`<option value="${n}" ${state.learning.newLimit===n?'selected':''}>${n===0?'只复习':n+' 个新词'}</option>`).join('')}</select><p class="small-note left">本地词库共 ${words.length.toLocaleString()} 词。每日量是上限，按已选范围执行。</p></section><section class="settings-block"><div class="settings-block-title"><span>${icon('arrow',21)}</span><h2>记忆方向</h2></div><div class="radio-tiles">${[['en-cn','英 → 中','先看单词，主动回忆词义'],['cn-en','中 → 英','先看词义，回想对应英文'],['spell','拼写','自己输入，不依赖选项'],['listen','听辨','听句子，再选择目标词义']].map(([value,title,note])=>`<label><input type="radio" name="direction" value="${value}" ${state.learning.direction===value?'checked':''}><span><strong>${title}</strong><small>${note}</small></span>${icon('check',18)}</label>`).join('')}</div></section><section class="settings-block"><h2>学习顺序</h2><select name="order" aria-label="学习顺序"><option value="book" ${state.learning.order==='book'?'selected':''}>按词书顺序</option><option value="random" ${state.learning.order==='random'?'selected':''}>轮换起点 · 演示随机模式</option><option value="review" ${state.learning.order==='review'?'selected':''}>有复习记录的词优先</option></select></section><button class="primary full">保存学习偏好</button></form><p class="small-note">设置影响本原型下一组任务；不运行真实 FSRS 或学习调度。</p>`;
}
